public class FixedServlet extends HttpServlet {
    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("user");
        // Fixed code: Sanitizing user input to prevent SQL injection
        String sanitizedInput = sanitize(userInput);
        response.getWriter().println("Hello, " + sanitizedInput);
    }

    private String sanitize(String input) {
        // Example sanitization: Remove any SQL-like characters
        return input.replaceAll("[;|&|<|>|'\"|\\]", "");
    }
}
